function layersHTML(){return `<div class="fin-lay" role="list" aria-label="Six layers, policy at the bottom, reporting at the top">${LAYERS.map(L=>`<button type="button" role="listitem" class="fin-ly ${L.id==="L3"?"core":""}" data-fin="layer" data-id="${L.id}"><span class="fin-lid">${L.id}</span><span class="fin-lt"><b>${E(L.n)}</b><small>${E(L.o)}</small></span>${L.id==="L3"?`<span class="fin-sws" aria-hidden="true">${F.colors.map(c=>`<i style="background:var(${cvar(c.id)})"></i>`).join("")}</span>`:`<span class="fin-ctag" title="The color tag is carried on this layer">color</span>`}</button>`).join("")}<span class="fin-rail" aria-hidden="true"><em>Color tag crosses layers</em></span></div>
 ${legend([["Color of money layer (L3), the source of the tag","--accent"],["Layer that carries the color tag","--p4"]])}<p class="small muted" style="margin:0">Spec section 3 text names layers 0, 1, 2, 3 and 5 as touched by color while its diagram also links layer 4; this prototype tags all six. Select a layer for its sources, outputs and screen.</p>`}
function dimExplorer(){const ls=leafLines();const id=F.dimLine&&ls.find(l=>l.id===F.dimLine)?F.dimLine:(ls.find(l=>l.id==="PR2-VEN")||ls[0]).id;const l=ls.find(x=>x.id===id);const en=effNature(l.nature,curGate(l),ctxOf(l));
 return `<div class="row" style="margin-bottom:10px"><label class="muted small" for="fin-dim">Pick a line</label><select id="fin-dim" class="fin" data-fin-change="dim" style="max-width:340px">${ls.map(x=>`<option value="${E(x.id)}" ${x.id===id?"selected":""}>${E(x.id+" "+x.name)}</option>`).join("")}</select></div>
 <div class="fin-dims"><div class="fin-dim"><small>1. Expense nature</small><b>${natChip(l.nature)}</b><p class="small muted">${isCap(l.nature)?"Capital: "+E(en.note[0]||"capitalized when the model's trigger is met."):"Operating: expensed as incurred."}${en.changed?" Treated today as "+E(NATN[en.n])+".":""}</p></div>
 <div class="fin-dim"><small>2. Color (funding type)</small><b>${cchip(l.color)}</b><p class="small muted">${l.color?"Fund code "+E(l.fund)+", source "+E(l.src||"none")+", assigned at "+E(l.gate)+".":"No color yet. Run the spend order at G1."}</p></div>
 <div class="fin-dim"><small>3. TBM position</small><b>${E(l.pool||"Unmapped")}</b><p class="small muted">${E([l.sub,l.tower&&"tower "+l.tower,l.sol&&((window.svcOf&&svcOf(l.sol))?(svcOf(l.sol).n||svcOf(l.sol).name):l.sol),"consumer "+consTxt(l.cons)].filter(Boolean).join(", "))}</p></div></div>
 <p class="small muted" style="margin:8px 0 0">No dimension is derived from another: this line could keep the same TBM position with a different color, or the same color with a different nature, and each combination has its own rule (<code>${E(l.color?(ruleFor(l.color,en.n,curGate(l))||{id:"none"}).id:"no rule yet")}</code>).</p>`}
function confTable(){return `<div class="tscroll"><table><thead><tr><th>Area</th><th>Confidence</th><th>Basis</th></tr></thead><tbody>${CONF0.map(r=>`<tr><td>${r[0]==="Overall"?"<b>Overall</b>":E(r[0])}</td><td><div class="fin-conf">${bar(r[1]*100,r[1]<.7?"warn":"")}<b class="num">${r[1].toFixed(2)}</b></div></td><td class="small">${E(r[2])}</td></tr>`).join("")}</tbody></table></div>`}
function attention(){const ex=exceptions().sort((a,b)=>(a.sev==="bad"?0:1)-(b.sev==="bad"?0:1)).slice(0,5);const dd=F.decs.filter(d=>d.st!=="Decided").sort((a,b)=>a.due.localeCompare(b.due)).slice(0,3);
 return `<div class="fin-att">${ex.map(e=>`<button type="button" class="fin-ar" data-fin="exc" data-id="${E(e.id)}"><span class="pill ${e.sev}">${E(e.type)}</span><span><b>${E(e.title)}</b><small>${E(e.owner)}</small></span></button>`).join("")}${dd.map(d=>`<button type="button" class="fin-ar" data-fin="dec" data-id="${d.id}"><span class="pill warn">${d.id}</span><span><b>${E(d.t)}</b><small>Due ${dt(d.due)} · ${E(d.owner)}</small></span></button>`).join("")}</div>`}
