 const ov=`${kpiRow([["Lines with a color",s.coloredPct+"%",s.colored+" of "+s.lines+" lines",{metric:"m_fin_colored"}],["Unfunded lines",String(s.unfunded),"need a color at G1",{metric:"m_fin_unfunded",cls:s.unfunded?"warn":""}],["Rules passing",s.rulesPass+" of 10","spec rules 10.5",{metric:"m_fin_rules"}],["Mapping confidence",s.mapConf+"%",s.lowConf+" Low lines",{metric:"m_fin_mapconf"}],["Open decisions",String(s.openD),"of 10, D-01 to D-10"]])}
 <div class="grid g2" style="margin-top:14px">${card("The six layers","Policy at the bottom, reporting at the top. Color of money is a layer of its own and a tag that every other layer carries.",layersHTML())}
 ${card("Needs attention","Exceptions from the live rule tests and decisions coming due. Select one for detail.",attention()+`<div class="row" style="margin-top:10px"><button class="btn" ${gt("fin_rules","fin_rules",1)}>Open the exception queue</button><button class="btn quiet" ${gt("fin_model","fin_model",2)}>Open the decision register</button></div>`)}</div>
 ${card("Three orthogonal dimensions on every money line","Nature, color and TBM position are independent. The Budgets and TBM modules already hold the line and its TBM position; this model adds the color and the nature rule.",dimExplorer(),"","margin-top:14px")}
 ${card("Confidence summary",`From the spec, section 0.1. Overall confidence is 0.75, below 0.8 mainly because Atlantic-specific inputs are missing. ${tag("INFERENCE")}`,confTable()+tagLegend())}`;
 const pr=`<div class="grid g2">${card("Design principles","Nine principles from spec section 2, with the evidence behind each.",`<ol class="fin-pr">${[["Three orthogonal dimensions on every money line","Expense nature, color and TBM position. No dimension is derived from another.",""],["Color is configuration, not code","Colors, attributes and rules live in a governed table. Adding or retiring a color is a change-controlled data change.",""],["Rules attach to color and nature together","Allowed use, capitalization, release and spend order are functions of color, nature and gate.",""],["Decide funding at the gate, not at the invoice","The color is assigned when the product or service is authorized, so budget, forecast and actuals inherit it.",""],["One line, one color","Shared costs are split into child lines by an explicit, versioned driver.","V-SECONDARY"],["Reconcile to the general ledger, always","TBM and color are overlays. Timing differences are offset explicitly, not hidden.","V-SECONDARY"],["Showback first","Report cost to consumers before any internal charging.","V-SECONDARY"],["Tag every judgment","Mapping method, confidence and notes travel with each mapped line.","V-PRIMARY"],["Borrow patterns, respect jurisdiction","public-sector standards board guidance does not govern a private not-for-profit's ledger; it is a reference pattern only.",""]].map(p=>`<li><b>${E(p[0])}</b> ${p[2]?tag(p[2]):""}<span class="small muted">${E(p[1])}</span></li>`).join("")}</ol>`)}
 <div style="display:grid;gap:14px;align-content:start">${card("Scope","Goal: one structure for IT budgeting and forecasting that combines four things.",`<ul class="fin-ul"><li>Accounting rules for how IT cost is recognized (standards board GAAP for Atlantic Systems' own books; public-sector standards board as a pattern only) ${tag("ASSUMPTION")}</li><li>TBM for cost structure and allocation ${stdChip("tbm","Cost pools, towers, solutions and consumers; color is a custom enrichment field.")}</li><li>ITIL for gates and the financial management practice ${stdChip("itil4","Service Financial Management and its funding model; each color's rules are the funding model.")} ${stdChip("itil5","ITIL 5 practice guides are still due; gates are Atlantic-defined so nothing depends on ITIL 5 stage names.")}</li><li>A color-of-money layer, parallel to how OpEx or CapEx drives treatment</li></ul>`)}
 ${card("Out of scope","Treated as configuration or left to others.",`<ul class="fin-ul"><li>How the funding classes themselves are funded: colors are configuration, not facts about Atlantic Systems</li><li>Tax treatment (software development cost rules, bonus depreciation)</li><li>Tool selection (ERP, TBM platform, ITSM platform)</li><li>Legal interpretation of any donor, grant or contract restriction</li></ul><p class="small" style="margin:8px 0 0"><b>Not legal or accounting advice.</b> Thresholds, restriction treatments and disclosures must be confirmed with the controller and auditors.</p>`)}</div></div>
 ${card("Layers, frameworks and where each lives in "+BRAND.name,"Select a row for detail.",`<div class="tscroll"><table><thead><tr><th>Layer</th><th>Source frameworks</th><th>Output</th><th>Screen</th></tr></thead><tbody>${LAYERS.slice().reverse().map(L=>`<tr><td><b>${L.id}</b> ${E(L.n)}</td><td class="small">${E(L.src)}</td><td class="small">${E(L.out)}</td><td><button type="button" class="btn quiet" data-fin="layer" data-id="${L.id}">Details</button></td></tr>`).join("")}</tbody></table></div>`,"",'margin-top:14px')}`;
