 const dr=`${kpiRow([["Decisions open",String(F.decs.filter(d=>d.st==="Open").length),"proposed: "+F.decs.filter(d=>d.st==="Proposed").length],["Decided",String(F.decs.filter(d=>d.st==="Decided").length),"of 10"],["Risks open",String(F.risks.filter(r=>r.st==="Open").length),"of 5"],["Next due",(F.decs.filter(d=>d.st!=="Decided").sort((a,b)=>a.due.localeCompare(b.due))[0]||{due:""}).due?dt(F.decs.filter(d=>d.st!=="Decided").sort((a,b)=>a.due.localeCompare(b.due))[0].due):"None","earliest open decision"]])}
 ${card("Decision and risk register","Working register. Select a row to update status, owner, due date or note; every change is written to the decision log.",btHTML({id:"fin_reg",h:420,rowH:56,key:"id",exportName:"fin-decisions-risks",facets:["k","st"],cols:[{k:"id",label:"ID",fmt:r=>`<b>${r.id}</b>`},{k:"k",label:"Kind"},{k:"t",label:"Decision or risk",wrap:1,fmt:r=>`<b>${E(r.t)}</b><br><small class="muted">${E(r.why||"")}</small>`},{k:"owner",label:"Owner",fmt:r=>E(r.owner)},{k:"due",label:"Due",fmt:r=>r.due?dt(r.due):"None"},{k:"st",label:"Status",fmt:r=>pill_(r.st,stCls[r.st])}],rows:regRows,open:id=>openReg(id)})+`<div class="row" style="margin-top:10px"><button class="btn primary" data-fin="newdec">Add a decision</button><button class="btn" data-fin="newrisk">Add a risk</button></div>`,"","margin-top:14px")}
 ${card("Decision log","Who changed what and why. This is the audit trail for the register.",F.dlog.length?`<ul class="fin-log">${F.dlog.slice(0,12).map(x=>`<li><b>${E(x.id)}</b> ${E(x.what)} <span class="muted small">${E(x.who)}, ${dt(x.t)}${x.why?". "+E(x.why):""}</span></li>`).join("")}</ul>`:empty("No changes yet"))}`;
 const asu=asuHTML(fy);
