function reconTab(){const fr=fundRecon(),gl=glRecon();const bad=fr.filter(r=>!r.ok).length;
 return `${kpiRow([["Fund codes reconciled",String(fr.length-bad)+" of "+fr.length,"within "+U(F.cfg.tol)+" ",{cls:bad?"warn":""}],["Difference after offsets",U(sum(fr,r=>Math.abs(r.diff))),"all fund codes",{metric:"m_fin_recon"}],["Timing offsets recorded",String(F.offsets.length),U(sum(F.offsets,o=>o.amt))+" in total"],["GL accounts off",String(gl.filter(g=>Math.abs(g.diff)>F.cfg.tol).length),"of "+gl.length]])}
 <div class="grid g2" style="margin-top:14px">${card("Reconciliation to the ledger by fund code","The general ledger is the system of record. Usage billed after month end creates a timing difference, which is offset explicitly, never hidden. Model spend is actuals through September.",`<div class="tscroll"><table class="fin-tb"><thead><tr><th>Fund code</th><th>Model spend</th><th>General ledger</th><th>Offsets</th><th>Difference</th><th>Status</th></tr></thead><tbody>${fr.map(r=>`<tr><td><code>${E(r.c.fund)}</code> ${cchip(r.c.id)}</td><td class="num">${U(r.model)}</td><td class="num">${U(r.gl)}</td><td class="num">${U(r.off)}</td><td class="num ${r.ok?"":"fin-neg"}"><b>${U(r.diff)}</b></td><td>${r.ok?pill_("Within tolerance","good"):`<button type="button" class="btn quiet" data-fin="offset" data-id="${E(r.c.fund)}">Record offset</button>`}</td></tr>`).join("")}</tbody></table></div><p class="small muted" style="margin:8px 0 0">Illustrative ledger totals. Tolerance ${U(F.cfg.tol)} ${tag("PLACEHOLDER")}. ${tag("V-SECONDARY")}</p>`)}
 ${card("Actuals by general ledger account (rule V7)","Anchors the cost pool: each account maps to a TBM pool or an asset account for capitalized cost.",`<div class="tscroll"><table><thead><tr><th>Account</th><th>Model actuals</th><th>General ledger</th><th>Difference</th></tr></thead><tbody>${gl.map(g=>`<tr><td><code>${g.acct}</code></td><td class="num">${U(g.model)}</td><td class="num">${U(g.gl)}</td><td class="num ${Math.abs(g.diff)>F.cfg.tol?"fin-neg":""}">${U(g.diff)}</td></tr>`).join("")}</tbody></table></div>`)}</div>
 ${card("Timing offsets","Each offset names the cause, the account and the fund code, so a difference is explained instead of absorbed.",F.offsets.length?`<ul class="fin-log">${F.offsets.map(o=>`<li><b>${U(o.amt)}</b> on account ${o.acct}, fund ${o.fund}: ${E(o.why)} <span class="muted small">${E(o.by)}, ${dt(o.t)}</span></li>`).join("")}</ul>`:empty("No offsets yet","Record one when usage is billed after month end."),"","margin-top:14px")}`}
function vColor(){syncM();const s=stats(),fc=forecast(),lap=sum(F.colors,c=>(fc.end[c.id]||{}).lapse||0),ph=F.colors.length;
 return `<div class="screen">${hero("Funding color (color of money)",`${F.colors.length} funding colors, each with its own rules`,`Headroom is <b>${U(s.headroom)}</b>${lap?` and <b>${U(lap)}</b> will lapse when the XR-T grant ends on Dec 31`:""}. All ${ph} colors are <b>placeholders</b> from the spec until Atlantic Systems supplies its real list (D-01). Every line carries exactly one color; shared cost is split by a versioned driver.`,`<div class="row">${fchip("m_fin_headroom")}${fchip("m_fin_recon")}${stdChip("tbm","TBM does not define a funding source, so color is a custom enrichment field governed here.")}${stdChip("cobit","Evidence, approvals and segregation for each color support governance objectives.")}</div>`)}${lensNote()}
 ${views("fin_color",["Balances and headroom","Colors","Rule matrix","Releases","Reconciliation"],[balTab(),colorsTab(),matrixTab(),relTab(),reconTab()])}${procCard("fin_color")}</div>`}

/* ---------- drawers and forms for color ---------- */
function colorDrawer(id){const c=colorOf(id);if(!c)return;const b=balances().col[id],fc=forecast().end[id]||{};const ls=leafLines().filter(l=>l.color===id);
 const months=["Jul","Aug","Sep"];let open=b.open;const wsum=sum(ACTW,x=>x);const roll=months.map((m,i)=>{const sp=Math.round(b.spend*ACTW[i]/wsum),au=i===0?b.auth:0;const cl=open+au-sp;const r={m,open,au,sp,cl};open=cl;return r});
 const eq=`Opening ${U(b.open)} + authorizations ${U(b.auth)} - spend ${U(b.spend)} - releases ${U(b.rel)} = <b>${U(b.close)}</b>`;
 openDrawer(`<div class="eyebrow">Color of money</div><div class="row" style="align-items:center;gap:10px"><h2 style="margin:4px 0">${cchip(id)} ${E(c.name)}</h2>${pill_(c.status,stCls[c.status])}${tag("PLACEHOLDER")}</div>
 <div class="story" data-role="story">${eq}. Forecast remaining ${U(b.fc)}, so headroom is <b>${U(b.head)}</b>${fc.lapse?`; <b>${U(fc.lapse)}</b> lapses on ${dt(fc.when)}`:""}.</div>
 <div class="row" style="margin:8px 0"><button class="btn primary" data-fin="editcolor" data-id="${id}">Edit attributes</button><button class="btn" data-fin="advance" data-id="${id}" ${c.status==="retired"?"disabled":""}>${c.status==="retired"?"Retired":"Move to "+LIFE[Math.min(4,LIFE.indexOf(c.status)+1)]}</button><button class="btn quiet" data-fin="newsrc" data-id="${id}">Add a funding source</button></div>
 <div class="dfullgrid"><div>${dtl([["Color id",`<code>${c.id}</code>`],["Fund code",`<code>${E(c.fund)}</code> <small class="muted">3-digit chart field</small> ${tag("V-SECONDARY")}`],["GAAP class",E(GAAPN[c.gaap])+" "+tag(c.gaap==="controller"?"ASSUMPTION":"V-PRIMARY")],["Restriction basis",E(BASISN[c.basis])],["Imposed by",E(c.imposed)],["Allowed use",E(c.allow)],["Unallowable",E(c.unallow)],["Availability",c.avail==="cash"?"Cash-based: spendable only after cash is received":"Budget-based: spendable once allocated"],["Spend-order rank",`<b>${c.rank}</b> (lower is spent first)`],["Capital rule",E(c.cap)+" "+tag(c.capT)],["Release event",E(c.rel)],["Expiry rule",E(c.exp)],["Carryforward",E(c.carry)],["Approval authority",E(c.auth)],["Evidence required",c.ev.map(e=>E(EVN[e]||e)).join(", ")],["Reporting",c.rep.map(E).join(", ")],["Allocation eligibility",consTxt(c.elig)],["Effective",dt(c.from)+" to "+(c.to?dt(c.to):"open")]])}</div>
 <div><h3>Funding sources</h3><div class="tscroll"><table><thead><tr><th>Source</th><th>Authorized</th><th>Spent</th><th>Closing</th><th>Dates</th></tr></thead><tbody>${b.srcs.map(s=>{const sc=sourcesOf(id).find(x=>x.id===s.id);return `<tr><td><code>${E(s.id)}</code><br><small class="muted">${E(sc.d)}</small></td><td class="num">${U(s.open+s.auth)}</td><td class="num">${U(s.spend)}</td><td class="num">${U(s.close)}</td><td class="small">${dt(sc.start)} to ${sc.end?dt(sc.end):"open"}</td></tr>`}).join("")}</tbody></table></div>
 <h3>Monthly roll, this fiscal year</h3><div class="tscroll"><table><thead><tr><th>Month</th><th>Opening</th><th>Authorizations</th><th>Spend</th><th>Closing</th></tr></thead><tbody>${roll.map(r=>`<tr><td>${r.m}</td><td class="num">${U(r.open)}</td><td class="num">${U(r.au)}</td><td class="num">${U(r.sp)}</td><td class="num">${U(r.cl)}</td></tr>`).join("")}</tbody></table></div><p class="small muted">Monthly spend follows the portfolio's actual spend profile; releases are shown on the Releases tab.</p></div></div>
 <h3>Lines funded by this color</h3>${lrHTML({id:"fin_lr_"+id,groups:[{key:"l",label:"Budget lines",rows:ls.map(l=>({id:l.id,t:l.id+" "+l.name,sub:U(l.fcst)+" forecast · "+NATN[l.nature],tag:l.gate,st:"info",go:()=>go("fin_budget")}))}],limit:6,search:true})}`)}
