function gateRuleForm(){openForm({id:"fin_grule_f",title:"Add a gate-specific rule",story:"Overrides the matrix cell for one color, nature and gate. Needs the color's approval authority.",submit:"Add rule",fields:[{k:"color",label:"Color",type:"select",opts:colorOpts()},{k:"nature",label:"Nature",type:"select",opts:natOpts},{k:"gate",label:"Gate",type:"select",opts:gOpts},{k:"allowed",label:"Allowed",type:"chips",opts:[["yes","Yes"],["conditional","Conditional"],["no","No"]]},{k:"conds",label:"Conditions",type:"multi",opts:Object.keys(CONDS).map(c=>[c,CONDS[c][0]]),show:v=>v.allowed==="conditional"},{k:"text",label:"Rule text",type:"longtext",req:true},{k:"appr",label:"Approval recorded",type:"toggle",req:true}],defaults:{color:"XR-P",nature:"capex_software_internal_use",gate:"G2",allowed:"conditional",conds:["c_prob"],appr:false},
 onSubmit:v=>{if(!v.appr)return fail("fin_grule_f","appr","Record the approval first");const key=v.color+"|"+v.nature+"|"+v.gate;if(F.rules[key])return fail("fin_grule_f","gate","That rule already exists");F.rules[key]={id:"R-"+v.color.replace("-","")+"-"+NATA[v.nature]+"-"+v.gate,color:v.color,nature:v.nature,gate:v.gate,allowed:v.allowed,conds:v.allowed==="conditional"?(v.conds||[]):[],text:v.text,ev:["time_and_effort_record","invoice"],approver:colorOf(v.color).auth,from:TODAY,ver:1,pending:null,ph:false};logE("rule",F.rules[key].id,"Gate-specific rule added",v.text,colorOf(v.color).auth);touch();audit("added gate rule",F.rules[key].id);render();return{toast:"Rule "+F.rules[key].id+" added"}}})}
function relForm(pre){pre=pre||{};openForm({id:"fin_rel_f",title:"Record a release",story:"Writes the release and an audit entry, updates the color balance (time and board releases) and the GAAP reclassification (purpose, time and capital releases on restricted colors). A capital release needs a placed-in-service date on the project; a release cannot exceed what the color holds.",submit:"Record release",
 fields:[{k:"color",label:"Color",type:"select",opts:colorOpts(),req:true},{k:"trig",label:"Trigger",type:"chips",opts:Object.keys(TL_TYPE).map(k=>[k,TL_TYPE[k]])},{k:"src",label:"Source",type:"select",opts:srcOpts(),req:true},{k:"proj",label:"Project (capital releases)",type:"select",opts:projOpts()},{k:"amt",label:"Amount",type:"money",req:true},{k:"date",label:"Event date",type:"date",req:true},{k:"evid",label:"Evidence reference",type:"text",req:true,ph:"Spend report, asset register entry, resolution"}],
 defaults:Object.assign({color:"XR-K",trig:"capital",src:"S-2026-021",proj:"PR1",date:TODAY,amt:"",evid:""},pre),
 live:v=>{const c=colorOf(v.color),b=balances().col[v.color],p=F.proj[v.proj]||{};const a=+v.amt||0;const msgs=[];if(v.trig==="capital"){msgs.push(p.pis?"Project "+v.proj+" placed in service "+dt(p.pis)+".":"Project "+v.proj+" has no placed-in-service date, so a capital release is blocked (rule V6).")}if(v.trig==="time"||v.trig==="board")msgs.push("This releases unspent balance. "+c.id+" holds "+U(b.close)+".");if(v.trig==="purpose")msgs.push("Spend on "+c.id+" so far is "+U(b.spend)+"; already released "+U(sum(F.rel.filter(r=>r.st==="recorded"&&r.color===c.id&&r.trig==="purpose"),r=>r.amt))+".");
  return `<div class="story">${msgs.map(E).join(" ")} GAAP effect: ${c.gaap==="with"&&["purpose","time","capital"].includes(v.trig)?"reclass from with to without donor restrictions "+tag("INFERENCE"):"no net asset class change"}. ${a?"Amount "+U(a)+".":""}</div>`},
 onSubmit:v=>{const c=colorOf(v.color),b=balances().col[v.color];const a=+v.amt||0;if(a<=0)return fail("fin_rel_f","amt","Amount must be above zero");
  if(sourcesOf(v.color).every(s=>s.id!==v.src))return fail("fin_rel_f","src","That source belongs to a different color");
  if(v.trig==="capital"&&!(F.proj[v.proj]||{}).pis)return fail("fin_rel_f","proj","Rule V6: the project needs a placed-in-service date first");
  if((v.trig==="time"||v.trig==="board")&&a>b.close)return fail("fin_rel_f","amt","Release is larger than the "+U(b.close)+" the color holds");
  if(v.trig==="time"&&v.date<(sourcesOf(v.color).find(s=>s.id===v.src)||{end:""}).end)return fail("fin_rel_f","date","A time release happens when the period has elapsed");
  const prior=F.rel.find(r=>r.color===v.color&&r.src===v.src&&r.trig===v.trig&&r.st!=="recorded"&&(!v.proj||r.proj===v.proj));const rec=recordRelease(v,prior&&prior.id);render();return{toast:rec.id+" recorded"+(rec.gaap?"; net assets reclassified "+U(rec.amt):"")}}})}
