function simRem(){const s=simS();if(s.ex==="cu"||s.live)return srcAvail("head");const rem={};F.sources.forEach(x=>rem[x.id]=0);Object.assign(rem,EXS[s.ex].bal);return rem}
function simRun(){const s=simS(),rem=simRem();return simCosts().map(c=>{const cc=Object.assign({},c,{pref:ovrOn()?s.pref:""});const r=spendCost(cc,{rem:Object.assign({},rem)});r.splits.forEach(sp=>takeFrom(sp.color,c.date||TODAY,sp.amt,rem));r.cost=c;return r})}
